function initTabs(){const e=document.querySelectorAll(".gingee-tab-btn"),n=document.querySelectorAll(".gingee-section");function t(t){e.forEach(e=>{const n=e.dataset.tab===t;e.classList.toggle("active",n),e.setAttribute("aria-selected",n?"true":"false")}),n.forEach(e=>{const n=e.id===t;e.classList.toggle("active",n)}),history.pushState?history.pushState(null,null,`#${t}`):location.hash=`#${t}`}e.forEach(e=>{e.addEventListener("click",()=>{t(e.dataset.tab)})});const i=window.location.hash.replace("#","");i&&document.getElementById(i)&&t(i)}function renderOverview(){const e=document.getElementById("overview-content");e&&"undefined"!=typeof GINGEE_INFO&&(e.innerHTML=`\n        <div class="overview-grid">\n            <div class="overview-card">\n                <h3><span>📍</span> Location & Geography</h3>\n                <p>Located in <strong>${GINGEE_INFO.location}</strong> at <strong>${GINGEE_INFO.coordinates}</strong>.</p>\n                <p>Spans over 11 sq km across three granite peaks rising <strong>${GINGEE_INFO.elevation}</strong>.</p>\n            </div>\n            <div class="overview-card">\n                <h3><span>👑</span> Citadel Legacy</h3>\n                <p>Original foundation: <strong>${GINGEE_INFO.builtEra}</strong> by <strong>${GINGEE_INFO.primaryBuilders}</strong>.</p>\n                <p>Recognized as a <strong>${GINGEE_INFO.status}</strong>.</p>\n            </div>\n            <div class="overview-card">\n                <h3><span>⚔️</span> The Troy of the East</h3>\n                <p>${GINGEE_INFO.nicknameReason}</p>\n            </div>\n        </div>\n    `)}function renderTimeline(){const e=document.getElementById("timeline-content");e&&"undefined"!=typeof TIMELINE_EVENTS&&(e.innerHTML=TIMELINE_EVENTS.map(e=>`\n        <div class="timeline-item">\n            <div class="timeline-dot"></div>\n            <div class="timeline-content">\n                <span class="timeline-year">${e.year}</span>\n                <h3 style="margin: 0.5rem 0; font-family: 'Playfair Display', serif; color: var(--gingee-gold);">${e.title}</h3>\n                <p style="color: var(--gingee-text-muted); font-size: 0.95rem; margin: 0;">${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderBuilders(){const e=document.getElementById("builder-content");e&&"undefined"!=typeof BUILDERS_LIST&&(e.innerHTML=`\n        <div class="builders-grid">\n            ${BUILDERS_LIST.map(e=>`\n                <div class="builder-card">\n                    <div class="builder-avatar">${e.icon}</div>\n                    <div class="builder-dynasty">${e.dynasty}</div>\n                    <h3 class="builder-name">${e.name}</h3>\n                    <div class="builder-era">${e.era} • <em>${e.role}</em></div>\n                    <p style="color: var(--gingee-text-muted); font-size: 0.95rem;">${e.contribution}</p>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderThreeHills(){const e=document.getElementById("three-hills-content");e&&"undefined"!=typeof THREE_HILLS&&(e.innerHTML=`\n        <div class="hills-grid">\n            ${THREE_HILLS.map(e=>`\n                <div class="hill-card">\n                    <div class="hill-card-header">\n                        <div class="hill-card-title">${e.icon} ${e.name}</div>\n                        <div class="hill-meta">\n                            <span>⛰️ Height: ${e.height}</span>\n                            <span>🧗 ${e.difficulty}</span>\n                        </div>\n                    </div>\n                    <div class="hill-card-body">\n                        <p style="color: var(--gingee-text-muted); line-height: 1.6;">${e.description}</p>\n                        <div style="font-weight: 700; margin-top: 1rem; color: var(--gingee-gold); font-size: 0.9rem;">KEY HIGHLIGHTS:</div>\n                        <div class="highlights-tags">\n                            ${e.highlights.map(e=>`<span class="tag">${e}</span>`).join("")}\n                        </div>\n                    </div>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderArchitecture(){const e=document.getElementById("architecture-content");e&&"undefined"!=typeof ARCH_FEATURES&&(e.innerHTML=`\n        <div class="arch-grid">\n            ${ARCH_FEATURES.map(e=>`\n                <div class="arch-card">\n                    <div class="arch-icon">${e.icon}</div>\n                    <h3 class="arch-title">${e.title}</h3>\n                    <span class="arch-type">${e.type}</span>\n                    <p style="color: var(--gingee-text-muted); font-size: 0.95rem;">${e.description}</p>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderStrategicImportance(){const e=document.getElementById("strategic-content");e&&(e.innerHTML='\n        <div class="overview-grid">\n            <div class="overview-card">\n                <h3><span>🗺️</span> Geographic Gateway</h3>\n                <p>Gingee held a pivotal position controlling northern Tamil Nadu, bridging the trade routes between the Deccan plateau and the Coromandel coastports.</p>\n            </div>\n            <div class="overview-card">\n                <h3><span>⚔️</span> The 8-Year Siege (1690–1698)</h3>\n                <p>During the Maratha-Mughal conflict, Maratha King Rajaram held out at Gingee against Mughal general Zulfiqar Khan for 8 long years. This epic stand drained Mughal coffers and tied down thousands of imperial troops.</p>\n            </div>\n            <div class="overview-card">\n                <h3><span>🛡️</span> Natural Chasm & Drawbridge</h3>\n                <p>The 60-foot deep natural ravine surrounding Rajagiri meant that even if an army breached the outer 13-km wall, the inner citadel remained completely inaccessible once the wooden drawbridge was raised.</p>\n            </div>\n        </div>\n    ')}function renderFacts(){const e=document.getElementById("facts-content");e&&"undefined"!=typeof INTERESTING_FACTS&&(e.innerHTML=`\n        <div class="facts-grid">\n            ${INTERESTING_FACTS.map(e=>`\n                <div class="fact-card">\n                    <div class="fact-header">\n                        <span class="fact-icon">${e.icon}</span>\n                        <div class="fact-title">${e.title}</div>\n                    </div>\n                    <p style="color: var(--gingee-text-muted); font-size: 0.95rem; margin: 0;">${e.fact}</p>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderGallery(){const e=document.getElementById("gallery-content");if(!e||"undefined"==typeof GALLERY_IMAGES)return;const n=["All",...new Set(GALLERY_IMAGES.map(e=>e.category))];function t(e){const n="All"===e?GALLERY_IMAGES:GALLERY_IMAGES.filter(n=>n.category===e),t=document.querySelector(".gallery-grid");t&&(t.innerHTML=n.map((e,n)=>`\n                <div class="gallery-item" data-index="${GALLERY_IMAGES.indexOf(e)}">\n                    <img src="${e.thumb}" alt="${e.alt}" loading="lazy" />\n                    <div class="gallery-overlay">\n                        <div class="gallery-caption">${e.caption}</div>\n                    </div>\n                </div>\n            `).join(""),attachGalleryEvents())}e.innerHTML=`\n        <div class="gallery-filters">\n            ${n.map(e=>`\n                <button class="filter-btn ${"All"===e?"active":""}" data-category="${e}">${e}</button>\n            `).join("")}\n        </div>\n        <div class="gallery-grid"></div>\n    `,t("All");const i=e.querySelectorAll(".filter-btn");i.forEach(e=>{e.addEventListener("click",()=>{i.forEach(e=>e.classList.remove("active")),e.classList.add("active"),t(e.dataset.category)})})}document.addEventListener("DOMContentLoaded",()=>{initTabs(),renderOverview(),renderTimeline(),renderBuilders(),renderThreeHills(),renderArchitecture(),renderStrategicImportance(),renderFacts(),renderGallery(),initLightbox()});let currentImgIndex=0;function initLightbox(){const e=document.getElementById("lightbox-modal");if(!e)return;const n=e.querySelector(".lightbox-close"),t=e.querySelector(".lightbox-prev"),i=e.querySelector(".lightbox-next");n&&n.addEventListener("click",closeLightbox),t&&t.addEventListener("click",()=>navigateLightbox(-1)),i&&i.addEventListener("click",()=>navigateLightbox(1)),e.addEventListener("click",n=>{n.target===e&&closeLightbox()}),document.addEventListener("keydown",n=>{e.classList.contains("active")&&("Escape"===n.key&&closeLightbox(),"ArrowLeft"===n.key&&navigateLightbox(-1),"ArrowRight"===n.key&&navigateLightbox(1))})}function attachGalleryEvents(){document.querySelectorAll(".gallery-item").forEach(e=>{e.addEventListener("click",()=>{openLightbox(parseInt(e.dataset.index,10))})})}function openLightbox(e){if("undefined"==typeof GALLERY_IMAGES||!GALLERY_IMAGES[e])return;currentImgIndex=e;const n=document.getElementById("lightbox-modal"),t=document.getElementById("lightbox-img"),i=document.getElementById("lightbox-caption");n&&t&&i&&(t.src=GALLERY_IMAGES[e].url,t.alt=GALLERY_IMAGES[e].alt,i.textContent=GALLERY_IMAGES[e].caption,n.classList.add("active"),n.setAttribute("aria-hidden","false"))}function closeLightbox(){const e=document.getElementById("lightbox-modal");e&&(e.classList.remove("active"),e.setAttribute("aria-hidden","true"))}function navigateLightbox(e){"undefined"!=typeof GALLERY_IMAGES&&(currentImgIndex=(currentImgIndex+e+GALLERY_IMAGES.length)%GALLERY_IMAGES.length,openLightbox(currentImgIndex))}